      'debut album', 'studio album', 'deluxe', 'tracklist',
      'track list', 'drops album', 'releases album'
    ]
  },
  'artists': {
    id: 41,
    slug: 'artists',
    keywords: [
      'interview', 'biography', 'profile', 'career',
      'story', 'journey', 'artist spotlight', 'meet',
      'rising star', 'emerging', 'artiste'
    ]
  },
  'featured': {
    id: 42,
    slug: 'featured',
    keywords: [
      'exclusive', 'breaking', 'major', 'grammy',
      'award', 'historic', 'first ever', 'milestone',
      'world tour', 'collaboration', 'collab', 'feat'
    ]
  },
  'dance-videos': {
    id: 85,
    slug: 'dance-videos',
