      'dance', 'video', 'music video', 'visual',
      'choreography', 'tiktok', 'challenge', 'moves',
      'official video', 'lyric video', 'visualizer'
    ]
  },
  'dj-highlights': {
    id: 42,
    slug: 'dj-highlights',
