      'dj', 'mix', 'mixtape', 'playlist', 'set',
      'afrobeats mix', 'deejay', 'spinall', 'turntable',
      'amapiano mix', 'dj set'
    ]
  },
  'event-recaps': {
    id: 42,
    slug: 'event-recaps',
    keywords: [
      'recap', 'review', 'concert review', 'festival recap',
      'night out', 'highlights from', 'what happened',
      'attended', 'photos from', 'recap of'
    ]
  },
  'upcoming-events': {
    id: 42,
    slug: 'upcoming-events',
    keywords: [
      'upcoming', 'tour', 'concert', 'festival', 'live',
      'tickets', 'performing', 'headline', 'announced',
      'dates', 'show', 'gig', 'coming to'
    ]
  },
  'community-moments': {
    id: 42,
    slug: 'community-moments',
    keywords: [
      'community', 'fan', 'fans react', 'twitter reacts',
      'social media', 'goes viral', 'reaction', 'fans say',
      'culture', 'movement', 'diaspora'
    ]
  }
